    pipeline: ["pembrolizumab", "cemiplimab", "hpv-vaccine"],
    openProblems: ["Node-positive disease: the best sequence of chemotherapy, radiotherapy and surgery is unknown; InPACT is designed to answer it.", "No approved systemic therapy beyond cisplatin combinations; checkpoint inhibitor trials (often HPV-stratified) are recruiting.", "Late presentation from stigma and delayed referral; awareness campaigns and rapid-access clinics are the response.", "Lymphoedema and sexual function after treatment; sentinel node biopsy and organ preservation reduce the toll."],
    targets: ["pd1", "egfr", "tp53"], technologies: ["sentinel-node", "brachytherapy", "cytotoxic-chemotherapy", "checkpoint-inhibitor", "hpv-vaccine", "robotic-surgery"],
